window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70f180036bd1f3eb"]={"versions": [{"id": "FIG-70f180036bd1f3eb", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Netzwerktopologie- und Systemkontext-Diagramm zur Darstellung vernetzter DoIP-Szenarien gemäß ISO 13400-1. Es veranschaulicht die Einbettung des AUTOSAR DoIP-Stacks in übergeordnete heterogene Netzwerkstrukturen (Fahrzeug-zu-Infrastruktur / Offboard-Diagnose), in denen mehrere Fahrzeuge und externe Test-/Diagnosegeräte über eine zentrale Vermittlungsinfrastruktur interagieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zentraler Netzwerkknoten / IP-Netzwerk (Switch/Router/Cloud):</strong> Dargestellt als zylindrisches Netzwerkelement im Zentrum der Topologie zur Vermittlung des IP-basierten Datenverkehrs.\n</li><li><strong>Fahrzeuge (DoIP-Nodes / DoIP-Gateways):</strong> Drei schematisch dargestellte Kraftfahrzeuge am unteren Bildrand, die als DoIP-fähige Entitäten mit bordeigenen Steuergeräten agieren.\n</li><li><strong>Externe Diagnose- und Managementsysteme:</strong>\n<ul class=\"fig-list\"><li>Zwei Notebooks/PCs (links und oben Mitte) als mobile oder stationäre Diagnosetester (DoIP-Clients).\n</li><li>Ein Server-System (oben rechts) als Backend-/Flottenmanagement- oder zentraler Diagnoseserver.\n</li></ul>\n</li><li><strong>Verbindungsmedien &amp; Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><strong>Kabelgebundene Verbindungen (Ethernet):</strong> Gekennzeichnet durch RJ45-Steckverbinder-Symbole an den gestrichelten Pfaden, repräsentieren standardisierte kabelgebundene Ethernet-Links (z. B. Werkstatt-Diagnoseanschluss nach ISO 13400-4).\n</li><li><strong>Drahtlose Verbindungen (WLAN / Mobilfunk):</strong> Gekennzeichnet durch Funkmast- und Wellensymbole, repräsentieren drahtlose IP-Verbindungen zur Flottenkommunikation oder drahtlosen Fahrzeugdiagnose.\n</li><li>Gestrichelte Linien kennzeichnen die logischen und physikalischen IP-basierten Kommunikationspfade zwischen den Endgeräten und dem zentralen Netzknoten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung zeigt keine zeitliche Sequenzabfolge oder Protokollphasen, sondern die statische Topologie für dynamische DoIP-Prozesse:</p>\n<ul class=\"fig-list\"><li>Aufbau der physikalischen und IP-Verbindung (kabellos via DHCP/Autoconfiguration oder kabelgebunden).\n</li><li>Routing Activation und Vehicle Identification / Announcement via UDP/TCP gemäß ISO 13400-2 über das vermittelnde Netzwerk.\n</li><li>Parallele oder selektive Diagnose-Sessions zwischen mehreren externen Testern/Servern und den einzelnen Fahrzeugen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Übersichtsschaubild (ISO 13400-1 Referenz). Es definiert keine proprietären AUTOSAR-Schnittstellen oder BSW-APIs, veranschaulicht jedoch die funktionale Anforderung an den DoIP-Treiber bzw. das DoIP-Modul, Mehrfachverbindungen, Routing über Standard-IP-Infrastrukturen sowie heterogene Medienanbindungen (Wired Ethernet und Wireless IP) abstrahiert von der physikalischen Schicht zu unterstützen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b97e8bb6220d799a", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Netzwerktopologie- und Systemkontext-Diagramm zur Darstellung vernetzter DoIP-Szenarien gemäß ISO 13400-1. Es veranschaulicht die Einbettung des AUTOSAR DoIP-Stacks in übergeordnete heterogene Netzwerkstrukturen (Fahrzeug-zu-Infrastruktur / Offboard-Diagnose), in denen mehrere Fahrzeuge und externe Test-/Diagnosegeräte über eine zentrale Vermittlungsinfrastruktur interagieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zentraler Netzwerkknoten / IP-Netzwerk (Switch/Router/Cloud):</strong> Dargestellt als zylindrisches Netzwerkelement im Zentrum der Topologie zur Vermittlung des IP-basierten Datenverkehrs.\n</li><li><strong>Fahrzeuge (DoIP-Nodes / DoIP-Gateways):</strong> Drei schematisch dargestellte Kraftfahrzeuge am unteren Bildrand, die als DoIP-fähige Entitäten mit bordeigenen Steuergeräten agieren.\n</li><li><strong>Externe Diagnose- und Managementsysteme:</strong>\n<ul class=\"fig-list\"><li>Zwei Notebooks/PCs (links und oben Mitte) als mobile oder stationäre Diagnosetester (DoIP-Clients).\n</li><li>Ein Server-System (oben rechts) als Backend-/Flottenmanagement- oder zentraler Diagnoseserver.\n</li></ul>\n</li><li><strong>Verbindungsmedien &amp; Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><strong>Kabelgebundene Verbindungen (Ethernet):</strong> Gekennzeichnet durch RJ45-Steckverbinder-Symbole an den gestrichelten Pfaden, repräsentieren standardisierte kabelgebundene Ethernet-Links (z. B. Werkstatt-Diagnoseanschluss nach ISO 13400-4).\n</li><li><strong>Drahtlose Verbindungen (WLAN / Mobilfunk):</strong> Gekennzeichnet durch Funkmast- und Wellensymbole, repräsentieren drahtlose IP-Verbindungen zur Flottenkommunikation oder drahtlosen Fahrzeugdiagnose.\n</li><li>Gestrichelte Linien kennzeichnen die logischen und physikalischen IP-basierten Kommunikationspfade zwischen den Endgeräten und dem zentralen Netzknoten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung zeigt keine zeitliche Sequenzabfolge oder Protokollphasen, sondern die statische Topologie für dynamische DoIP-Prozesse:</p>\n<ul class=\"fig-list\"><li>Aufbau der physikalischen und IP-Verbindung (kabellos via DHCP/Autoconfiguration oder kabelgebunden).\n</li><li>Routing Activation und Vehicle Identification / Announcement via UDP/TCP gemäß ISO 13400-2 über das vermittelnde Netzwerk.\n</li><li>Parallele oder selektive Diagnose-Sessions zwischen mehreren externen Testern/Servern und den einzelnen Fahrzeugen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Übersichtsschaubild (ISO 13400-1 Referenz). Es definiert keine proprietären AUTOSAR-Schnittstellen oder BSW-APIs, veranschaulicht jedoch die funktionale Anforderung an den DoIP-Treiber bzw. das DoIP-Modul, Mehrfachverbindungen, Routing über Standard-IP-Infrastrukturen sowie heterogene Medienanbindungen (Wired Ethernet und Wireless IP) abstrahiert von der physikalischen Schicht zu unterstützen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-70f180036bd1f3eb", "to": "FIG-b97e8bb6220d799a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
